"""File tools: inventory, spreadsheet, PDF (text parser or LLM reader)."""

from __future__ import annotations

import re
from pathlib import Path

import neatlogs
from openpyxl import load_workbook
from pydantic import BaseModel

from spendradar import llm

MONEY = re.compile(r"(-?[\d,]+\.\d{2})\s*$")


class ToolError(Exception):
    """A tool could not produce a result; the loop decides how to recover."""


@neatlogs.span(kind="TOOL", name="act:list_files", tool_name="list_files")
def list_files(folder: str) -> list[dict]:
    root = Path(folder)
    return [{"path": str(p.relative_to(root)), "bytes": p.stat().st_size, "suffix": p.suffix.lower()}
            for p in sorted(root.rglob("*")) if p.is_file() and not p.name.startswith(".")]


@neatlogs.span(kind="TOOL", name="act:read_spreadsheet", tool_name="read_spreadsheet")
def read_spreadsheet(path: str, sheet: str, first_row: int = 1, last_row: int | None = None) -> list[dict]:
    """Rows as dicts keyed by the header row, each with its 1-based sheet row number."""
    try:
        wb = load_workbook(path, data_only=True, read_only=True)
        ws = wb[sheet]
    except Exception as e:
        raise ToolError(f"cannot open {path}!{sheet}: {e}") from e
    rows = list(ws.iter_rows(values_only=True))
    header_idx = next(i for i, r in enumerate(rows) if r and r[0] == "category")
    header = [str(h) if h is not None else "" for h in rows[header_idx]]
    out = []
    for i, r in enumerate(rows[header_idx + 1:], start=header_idx + 2):
        if i < first_row or (last_row and i > last_row) or not r or r[0] is None:
            continue
        out.append({"_row": i, **{h: v for h, v in zip(header, r)}})
    return out


class InvoiceLine(BaseModel):
    description: str
    amount: float


class InvoiceExtract(BaseModel):
    invoice_number: str
    vendor: str
    cost_centre: str
    invoice_date: str
    lines: list[InvoiceLine]
    stated_total: float


def _parse_invoice_text(text: str) -> InvoiceExtract:
    fields: dict[str, str] = {}
    lines: list[InvoiceLine] = []
    total = None
    in_items = False
    all_lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    for ln in all_lines:
        if ":" in ln and not in_items:
            k, _, v = ln.partition(":")
            fields[k.strip().lower()] = v.strip()
        if ln.startswith("Description"):
            in_items = True
            continue
        m = MONEY.search(ln)
        if ln.upper().startswith("TOTAL") and m:
            total = float(m.group(1).replace(",", ""))
            in_items = False
        elif in_items and m:
            lines.append(InvoiceLine(description=ln[: m.start()].strip(), amount=float(m.group(1).replace(",", ""))))
    if total is None or not lines:
        raise ToolError("text parser found no line items / total")
    return InvoiceExtract(invoice_number=fields.get("invoice no.", ""), vendor=all_lines[0],
                          cost_centre=fields.get("cost centre", ""), invoice_date=fields.get("invoice date", ""),
                          lines=lines, stated_total=total)


@neatlogs.span(kind="TOOL", name="act:read_pdf", tool_name="read_pdf")
def read_pdf(path: str, mode: str = "text") -> dict:
    """mode='text': pdfplumber + deterministic parse. mode='llm': Gemini reads the PDF bytes."""
    p = Path(path)
    if mode == "text":
        import pdfplumber

        try:
            with pdfplumber.open(p) as pdf:
                text = "\n".join(page.extract_text() or "" for page in pdf.pages)
        except Exception as e:
            raise ToolError(f"pdfplumber could not open file: {type(e).__name__}: {str(e)[:120]}") from e
        if not text.strip():
            raise ToolError("no text layer (likely a scanned image)")
        inv = _parse_invoice_text(text)
        return {"extract": inv.model_dump(), "parser": "pdfplumber", "llm": None}
    if mode == "llm":
        data = p.read_bytes()
        try:
            res = llm.complete(
                "extract",
                "Extract this invoice exactly as printed. Amounts as numbers without separators. "
                "Do not compute or correct anything; copy the stated total as printed.",
                schema=InvoiceExtract, attachments=[(data, "application/pdf")])
        except llm.LLMError as e:
            raise ToolError(f"LLM PDF reader failed: {str(e)[:160]}") from e
        return {"extract": res.parsed.model_dump(), "parser": f"llm:{res.model}",
                "llm": {"model": res.model, "tokens_in": res.tokens_in, "tokens_out": res.tokens_out,
                        "latency_s": res.latency_s, "cached": res.cached}}
    raise ToolError(f"unknown mode {mode!r}")

"""Crustdata tools with response cache, backoff, credit cap and fault injection."""

from __future__ import annotations

import hashlib
import json
import os
import random
import time
from datetime import datetime, timezone
from pathlib import Path

import httpx
import neatlogs
import yaml

from spendradar import faults
from spendradar.tools.files import ToolError

BASE = "https://api.crustdata.com"
CACHE = Path("cache/crustdata")
CFG = yaml.safe_load(Path("config.yaml").read_text())["crustdata"]
ENRICH_FIELDS = ["basic_info", "headcount", "funding", "hiring", "news"]
ENRICH_CREDITS = 2.0
JOB_RESULT_CREDITS = 0.03


class CreditBudget:
    def __init__(self, cap: float):
        self.cap, self.spent = cap, 0.0

    def charge(self, credits: float) -> None:
        if self.spent + credits > self.cap:
            raise ToolError(f"crustdata credit cap reached ({self.spent:.2f}/{self.cap} credits)")
        self.spent += credits


BUDGET = CreditBudget(CFG["max_credits_per_run"])


def _key(path: str, body: dict) -> str:
    return hashlib.sha256(json.dumps([path, body], sort_keys=True).encode()).hexdigest()[:24]


def _post(path: str, body: dict, est_credits: float) -> dict:
    """POST with cache → retries/backoff → stale-cache fallback. Returns {body, fetched_at, from_cache, ...}."""
    CACHE.mkdir(parents=True, exist_ok=True)
    cpath = CACHE / f"{_key(path, body)}.json"
    cached = json.loads(cpath.read_text()) if cpath.exists() else None
    if cached and not faults.active():
        return {**cached, "from_cache": True}
    headers = {"authorization": f"Bearer {os.environ['CRUSTDATA_API_KEY']}",
               "content-type": "application/json", "x-api-version": "2025-11-01"}
    errors = []
    for attempt in range(CFG["retries"] + 1):
        with neatlogs.trace(f"http:crustdata{path}", kind="TOOL") as span:
            span.set_attribute("spendradar.attempt", attempt)
            try:
                if faults.fire("crustdata:429"):
                    raise httpx.HTTPStatusError("[injected] 429 Too Many Requests", request=None, response=None)
                if faults.fire("crustdata:timeout"):
                    raise httpx.ReadTimeout("[injected] read timeout")
                BUDGET.charge(est_credits)
                r = httpx.post(BASE + path, json=body, headers=headers, timeout=60)
                if r.status_code == 429 or r.status_code >= 500:
                    raise httpx.HTTPStatusError(f"{r.status_code}", request=r.request, response=r)
                r.raise_for_status()
                out = {"body": r.json(), "fetched_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
                       "endpoint": path, "request_id": r.headers.get("x-request-id", ""), "credits": est_credits}
                cpath.write_text(json.dumps(out))
                span.set_attribute("spendradar.outcome", "ok")
                return {**out, "from_cache": False}
            except ToolError:
                raise
            except (httpx.HTTPStatusError, httpx.TransportError) as e:
                errors.append(str(e)[:120])
                span.set_attribute("spendradar.outcome", f"retryable: {str(e)[:120]}")
        if attempt < CFG["retries"]:
            time.sleep((2 ** attempt) * 1.0 + random.random())
    if cached:  # recovery: stale cache beats nothing
        with neatlogs.trace("recover:crustdata_cache_fallback", kind="CHAIN") as span:
            span.set_attribute("spendradar.errors", json.dumps(errors))
        return {**cached, "from_cache": True, "stale_fallback": True, "errors": errors}
    raise ToolError(f"crustdata {path} failed after {CFG['retries'] + 1} attempts: {errors[-1]}")


@neatlogs.span(kind="TOOL", name="act:crustdata_company", tool_name="crustdata_company")
def crustdata_company(domain: str) -> dict:
    res = _post("/company/enrich", {"domains": [domain], "fields": ENRICH_FIELDS}, ENRICH_CREDITS)
    body = res["body"]
    matches = body[0].get("matches") if isinstance(body, list) and body else None
    if not matches:
        raise ToolError(f"no Crustdata match for {domain}")
    return {**res, "company_data": matches[0]["company_data"], "body": None}


@neatlogs.span(kind="TOOL", name="act:crustdata_jobs", tool_name="crustdata_jobs")
def crustdata_jobs(domain: str, since: str, category: str | None = None, limit: int = 60) -> dict:
    conds = [{"field": "company.basic_info.primary_domain", "type": "=", "value": domain},
             {"field": "metadata.date_added", "type": "=>", "value": since}]
    if category:
        conds.append({"field": "job_details.category", "type": "=", "value": category})
    body = {"filters": {"op": "and", "conditions": conds}, "limit": limit,
            "fields": ["job_details.title", "job_details.category", "metadata.date_added"],
            "sorts": [{"field": "metadata.date_added", "order": "desc"}]}
    res = _post("/job/search", body, JOB_RESULT_CREDITS * limit)
    jobs = res["body"].get("job_listings") or []
    titles = [{"title": (j.get("job_details") or {}).get("title"),
               "category": (j.get("job_details") or {}).get("category"),
               "date_added": (j.get("metadata") or {}).get("date_added")} for j in jobs]
    return {**res, "body": None, "total_count": res["body"].get("total_count"), "titles": titles}

"""Deterministic maths: competitor signals, people-cost estimates, policy comparison.

The LLM never computes anything that reaches the report; everything numeric is here.
"""

from __future__ import annotations

import statistics
from datetime import date, datetime

from spendradar.models import CompetitorProfile, CompetitorSignal, Source

# Crustdata role / function names → our categories. ml_ai is derived (no ML role exists).
ROLE_MAP = {"engineering": ["Engineering"], "sales": ["Sales", "Business Development"], "marketing": ["Marketing"]}


def _src(domain: str, fetched_at: str, locator: str, note: str = "") -> Source:
    return Source(kind="crustdata", ref=f"/company/enrich?domain={domain}", locator=locator,
                  fetched_at=fetched_at, note=note)


def profile_from_enrich(name: str, domain: str, cd: dict, fetched_at: str) -> CompetitorProfile:
    hc = cd.get("headcount") or {}
    prof = CompetitorProfile(name=name, domain=domain, total_headcount=hc.get("total"),
                             total_as_of=fetched_at[:10], funding={
                                 k: (cd.get("funding") or {}).get(k) for k in
                                 ("total_investment_usd", "last_round_type", "last_round_amount_usd",
                                  "last_fundraise_date")})
    roles = hc.get("by_role_absolute") or {}
    funcs = (hc.get("by_function_timeseries") or {}).get("CURRENT_FUNCTION") or {}
    for cat, names in ROLE_MAP.items():
        present = [n for n in names if n in roles]
        if present:
            prof.signals.append(CompetitorSignal(
                name="role_headcount", category=cat, headcount=float(sum(roles[n] for n in present)),
                as_of=fetched_at[:10],
                source=_src(domain, fetched_at, "headcount.by_role_absolute." + "+".join(present))))
        series = [funcs[n] for n in names if funcs.get(n)]
        if series:
            last_date = max(s[-1]["date"][:10] for s in series)
            value = sum(s[-1]["employee_count"] for s in series)
            prof.signals.append(CompetitorSignal(
                name="function_timeseries", category=cat, headcount=float(value), as_of=last_date,
                source=_src(domain, fetched_at, "headcount.by_function_timeseries.CURRENT_FUNCTION." + "+".join(
                    n for n in names if funcs.get(n)) + f"[{last_date}]")))
        if not present and not series:
            prof.missing.append(f"{cat}: no role or function headcount")
    if not (cd.get("hiring") or {}).get("recent_titles_csv"):
        prof.missing.append("hiring: no recent job titles")
    prof.news = [{"date": n.get("article_publish_date"), "title": n.get("article_title"), "url": n.get("article_url")}
                 for n in (cd.get("news") or [])[:25]]
    return prof


def recent_titles(cd: dict) -> list[str]:
    csv = ((cd.get("hiring") or {}).get("recent_titles_csv") or "")
    return [t.strip() for t in csv.split(",") if t.strip()]


def ml_share(titles: list[str], classes: dict[str, dict]) -> tuple[float, int, int] | None:
    """Share of engineering-ish titles classified ml_ai. Returns (share, ml, eng_total)."""
    labelled = [classes[t]["category"] for t in titles if t in classes]
    eng_like = [c for c in labelled if c in ("engineering", "ml_ai")]
    if len(eng_like) < 3:
        return None
    ml = sum(1 for c in eng_like if c == "ml_ai")
    return ml / len(eng_like), ml, len(eng_like)


def add_ml_signals(prof: CompetitorProfile, samples: dict[str, tuple[list[str], Source]],
                   classes: dict[str, dict]) -> None:
    """ml_ai headcount = engineering role headcount × ML share of an independent title sample."""
    eng = next((s for s in prof.signals if s.category == "engineering" and s.name == "role_headcount"), None)
    if not eng:
        prof.missing.append("ml_ai: no engineering headcount to scale")
        return
    for sample_name, (titles, src) in samples.items():
        r = ml_share(titles, classes)
        if r is None:
            prof.missing.append(f"ml_ai: too few classified titles in {sample_name}")
            continue
        share, ml, n = r
        prof.signals.append(CompetitorSignal(
            name=f"ml_share_{sample_name}", category="ml_ai", headcount=round(eng.headcount * share, 1),
            as_of=src.fetched_at[:10],
            source=Source(kind="derived", ref=src.ref, locator=src.locator,
                          fetched_at=src.fetched_at,
                          note=f"{ml}/{n} engineering titles classified ml_ai × engineering headcount {eng.headcount:.0f}")))


def category_range(prof: CompetitorProfile, cat: str) -> tuple[float, float, int] | None:
    vals = [s.headcount for s in prof.signals if s.category == cat]
    if not vals:
        return None
    return min(vals), max(vals), len(vals)


def signal_agreement(prof: CompetitorProfile, cat: str) -> float | None:
    """1.0 = signals agree exactly; low/high ratio otherwise. None if < 2 signals."""
    r = category_range(prof, cat)
    if not r or r[2] < 2 or r[1] == 0:
        return None
    return r[0] / r[1]


def days_old(as_of: str, today: date | None = None) -> int:
    d = datetime.fromisoformat(as_of[:10]).date()
    return ((today or date.today()) - d).days


def our_position(budget: dict) -> dict:
    """budget = {'headcount_end': {cat: n}, 'people_cost': {cat: usd}} from the verified spreadsheet."""
    total = sum(budget["headcount_end"].values())
    return {cat: {"headcount": hc, "share": hc / total, "people_cost": budget["people_cost"].get(cat)}
            for cat, hc in budget["headcount_end"].items()} | {"_total": total}


def competitor_shares(profiles: list[CompetitorProfile], cat: str) -> list[dict]:
    out = []
    for p in profiles:
        r = category_range(p, cat)
        if not r or not p.total_headcount:
            continue
        out.append({"name": p.name, "low": r[0] / p.total_headcount, "high": r[1] / p.total_headcount,
                    "signals": r[2]})
    return out


def compare(ours: dict, shares: list[dict], rule: dict, loaded_cost: float) -> dict:
    """Policy check on share of headcount vs competitor median, plus gap in heads and USD (estimate)."""
    if not shares:
        return {"status": "no_data"}
    med_low = statistics.median(s["low"] for s in shares)
    med_high = statistics.median(s["high"] for s in shares)
    mid = (med_low + med_high) / 2
    our_share = ours["share"]
    pct = rule["pct"] / 100
    if rule["rule"] == "within_pct_of_median":
        violated = abs(our_share - mid) > pct * mid
    elif rule["rule"] == "at_least_pct_of_median":
        violated = our_share < pct * mid
    else:
        raise ValueError(f"unknown rule {rule['rule']}")
    total = ours["_total"]
    gap_heads_low, gap_heads_high = med_low * total - ours["headcount"], med_high * total - ours["headcount"]
    return {"status": "ok", "our_share": our_share, "median_low": med_low, "median_high": med_high,
            "median_mid": mid, "violated": violated, "n_competitors": len(shares),
            "gap_heads": (gap_heads_low, gap_heads_high),
            "gap_usd": (gap_heads_low * loaded_cost, gap_heads_high * loaded_cost)}

